module TopModule (
    input  clk,
    input  load,
    input  [9:0] data,
    output reg tc
);

    reg [9:0] counter;
    reg [9:0] next_counter;
    reg next_tc;

    always @(posedge clk) begin
        if (load) begin
            next_counter <= data;
            next_tc <= 1'b0;
        end else begin
            if (counter == 10'd0) begin
                next_tc <= 1'b1;
            end else begin
                next_counter <= counter - 1;
                next_tc <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        counter <= next_counter;
        tc <= next_tc;
    end

endmodule

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Next state logic
    // Determine next_state based on current state and input 'in'
    // Using one-hot encoding, only one bit is active at a time

    // State A (state[0])
    // in=0 -> A, in=1 -> B
    // next_state = (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) : 4'b0000
    // State B (state[1])
    // in=0 -> C, in=1 -> B
    // next_state = (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) : 4'b0000
    // State C (state[2])
    // in=0 -> A, in=1 -> D
    // next_state = (state == 4'b0100) ? (in ? 4'b1000 : 4'b0001) : 4'b0000
    // State D (state[3])
    // in=0 -> C, in=1 -> B
    // next_state = (state == 4'b1000) ? (in ? 4'b0010 : 4'b0100) : 4'b0000

    // Combine all cases
    always @(*) begin
        next_state = 4'b0000;
        if (state == 4'b0001) begin
            if (in) next_state = 4'b0010; // B
            else next_state = 4'b0001;   // A
        end else if (state == 4'b0010) begin
            if (in) next_state = 4'b0010; // B
            else next_state = 4'b0100;   // C
        end else if (state == 4'b0100) begin
            if (in) next_state = 4'b1000; // D
            else next_state = 4'b0001;   // A
        end else if (state == 4'b1000) begin
            if (in) next_state = 4'b0010; // B
            else next_state = 4'b0100;   // C
        end
    end

    // Output logic
    // Output is 0 for states A, B, C and 1 for state D
    always @(*) begin
        if (state == 4'b1000) begin
            out = 1;
        end else begin
            out = 0;
        end
    end

endmodule

