                    end else begin
                        next_state <= WALK_LEFT;
                    end
                end
            endcase

            current_state <= next_state;
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (current_state == FALLING) begin
            aaah <= 1'b1;
            digging <= 1'b0;
            walk_left <= 1'b0;
            walk_right <= 1'b0;
        end else if (current_state == DIGGING) begin
            digging <= 1'b1;
            walk_left <= 1'b0;
            walk_right <= 1'b0;
            aaah <= 1'b0;
        end else begin
            digging <= 1'b0;
            if (prev_direction) begin
                walk_left <= 1'b1;
