module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the grid
    reg [255:0] current_state;

    // Next state of the grid
    reg [255:0] next_state;

    // Internal logic to compute next state
    always @(posedge clk) begin
        if (load) begin
            current_state <= data;
        end else begin
            current_state <= next_state;
        end
    end

    // Compute next state based on current_state
    always @(*) begin
        next_state = 256'h0;

        for (integer i = 0; i < 16; i = i + 1) begin
            for (integer j = 0; j < 16; j = j + 1) begin
                integer count = 0;

                // Check all 8 neighbors
                for (integer dx = -1; dx <= 1; dx = dx + 1) begin
                    for (integer dy = -1; dy <= 1; dy = dy + 1) begin
                        if (dx == 0 && dy == 0) continue;

                        integer ni = (i + dx + 16) % 16;
                        integer nj = (j + dy + 16) % 16;

                        if (current_state[(ni * 16) + nj]) count = count + 1;
                    end
                end

                integer pos = (i * 16) + j;
                if (current_state[pos]) begin
                    if (count == 2) begin
                        next_state[pos] = 1;
                    end else if (count == 3) begin
                        next_state[pos] = 1;
                    end
                end else begin
                    if (count == 3) begin
                        next_state[pos] = 1;
                    end
                end
            end
        end
    end

    // Output the current state
    assign q = current_state;

endmodule

module TopModule (
