            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state based on current state and inputs
            case (current_state)
                WALK_LEFT: begin
                    // Check for fall
                    if (!ground) begin
                        next_state <= FALLING;
                        prev_direction <= 1'b1;
                    end else if (dig) begin
                        next_state <= DIGGING;
                    end else if (bump_right) begin
                        next_state <= WALK_RIGHT;
                    end else begin
                        next_state <= WALK_LEFT;
                    end
                end

                WALK_RIGHT: begin
                    if (!ground) begin
                        next_state <= FALLING;
                        prev_direction <= 1'b0;
                    end else if (dig) begin
                        next_state <= DIGGING;
                    end else if (bump_left) begin
                        next_state <= WALK_LEFT;
                    end else begin
                        next_state <= WALK_RIGHT;
                    end
                end

                FALLING: begin
                    if (ground) begin
                        next_state <= WALK_LEFT;
                    end else begin
                        next_state <= FALLING;
                    end
                end

                DIGGING: begin
                    if (!ground) begin
                        next_state <= FALLING;
                    end else if (dig) begin
                        next_state <= DIGGING;
                    end else begin
                        next_state <= WALK_LEFT;
                    end
                end
            endcase

            current_state <= next_state;
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (current_state == FALLING) begin
            aaah <= 1'b1;
            digging <= 1'b0;
