    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'd0;
            prev_s <= 3'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Determine current sensor state
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        // Above s[2]
                        state <= 2'd3;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else begin
                        // Between s[2] and s[1]
                        state <= 2'd2;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end else begin
                    // Between s[1] and s[0]
                    state <= 2'd1;
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            end else begin
                // Below s[0]
                state <= 2'd0;
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Check if the previous level was lower than the current level
    always @(posedge clk) begin
        if (state == 2'd0 && prev_s == 3'd0) begin
            // No change, do nothing
        end else if (state == 2'd1 && prev_s == 3'd1) begin
            // No change, do nothing
        end else if (state == 2'd2 && prev_s == 3'd2) begin
            // No change, do nothing
        end else if (state == 2'd3 && prev_s == 3'd3) begin
            // No change, do nothing
        end else begin
            // Previous level was lower than current level
            dfr <= 1'b1;
        end
    end

endmodule

