        if (reset) begin
            current_state <= STATE_LOW;
            prev_s <= 3'b000; // Reset to no sensors asserted (simulate low level)
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            current_state <= next_state;
            prev_s <= s;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;

        // Determine current sensor state
        case (s)
            3'b111: next_state = STATE_HIGH; // Above s[2]
            3'b110: next_state = STATE_MID2; // Between s[2] and s[1]
            3'b100: next_state = STATE_MID1; // Between s[1] and s[0]
            3'b000: next_state = STATE_LOW;  // Below s[0]
            default: next_state = current_state;
        endcase
    end

    // Output logic
    always @(posedge clk) begin
        case (current_state)
            STATE_LOW: begin
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            STATE_MID1: begin
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            STATE_MID2: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            STATE_HIGH: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end
        endcase
    end

    // Check if previous level was lower than current level (for dfr)
    always @(posedge clk) begin
        if (prev_s < s) begin
            dfr <= 1'b1;
        end else begin
            dfr <= 1'b0;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition
    typedef enum reg [2:0] {
        STATE_LOW,      // Below s[0], all flow valves open
        STATE_MID1,     // Between s[1] and s[0], fr0, fr1 open
        STATE_MID2,     // Between s[2] and s[1], fr0 open
        STATE_HIGH      // Above s[2], no flow
    } state_t;

    state_t current_state, next_state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_LOW;
            prev_s <= 3'b000; // Reset to no sensors asserted (simulate low level)
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            current_state <= next_state;
            prev_s <= s;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;

        // Determine current sensor state
        case (s)
            3'b111: next_state = STATE_HIGH; // Above s[2]
            3'b110: next_state = STATE_MID2; // Between s[2] and s[1]
            3'b100: next_state = STATE_MID1; // Between s[1] and s[0]
            3'b000: next_state = STATE_LOW;  // Below s[0]
            default: next_state = current_state;
        endcase
    end

    // Output logic
    always @(posedge clk) begin
        case (current_state)
            STATE_LOW: begin
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            STATE_MID1: begin
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            STATE_MID2: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            STATE_HIGH: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end
        endcase
    end

    // Check if previous level was lower than current level (for dfr)
    always @(posedge clk) begin
        if (prev_s < s) begin
            dfr <= 1'b1;
        end else begin
            dfr <= 1'b0;
        end
    end

endmodule
